mapper.select:
SELECT 
FROM chatbi.bid_biz_win_bid

    AND province = #{province}
    AND city = #{city}
    AND industry = #{industry}
    AND info_type = #{infoType}
    AND tenderer LIKE CONCAT('%', #{tenderer}, '%')
    AND win_tenderer LIKE CONCAT('%', #{winTenderer}, '%')

        AND (
          title LIKE CONCAT('%', #{keyword}, '%')
          OR project_name LIKE CONCAT('%', #{keyword}, '%')
          OR product LIKE CONCAT('%', #{keyword}, '%')
          OR win_tenderer LIKE CONCAT('%', #{keyword}, '%')
        )

    AND win_bid_price >= #{minBudgetYuan}
    AND win_bid_price <= #{maxBudgetYuan}
    AND publish_time >= #{beginDate}
    AND publish_time <= #{endDate}

ORDER BY publish_time DESC, id DESC
LIMIT #{limit}

SELECT 
FROM chatbi.bid_biz_win_bid
WHERE id = #{id}

SELECT win_tenderer AS winner, COUNT(*) AS cnt, COALESCE(SUM(win_bid_price), 0) AS amount_yuan FROM chatbi.bid_biz_win_bid
win_tenderer IS NOT NULL AND win_tenderer != ''
GROUP BY win_tenderer ORDER BY cnt DESC, amount_yuan DESC LIMIT #{limit}

SELECT
    win_tenderer AS company_name,
    COUNT(*) AS win_count,
    COALESCE(SUM(win_bid_price), 0) AS total_amount,
    MAX(publish_time) AS latest_win_time
FROM chatbi.bid_biz_win_bid

    win_tenderer IS NOT NULL AND win_tenderer != ''



                title LIKE CONCAT('%', #{kw}, '%')
                OR project_name LIKE CONCAT('%', #{kw}, '%')
                OR product LIKE CONCAT('%', #{kw}, '%')
                OR win_tenderer LIKE CONCAT('%', #{kw}, '%')




        AND province IN

            #{p}


    AND win_bid_price >= #{minPrice}
    AND win_bid_price <= #{maxPrice}
    AND publish_time >= #{beginDate}
    AND publish_time <= #{endDate}

GROUP BY win_tenderer
ORDER BY win_count DESC, total_amount DESC
LIMIT #{limit}

SELECT keywords AS brand, province AS province, COUNT(*) AS win_count, COALESCE(SUM(win_bid_price), 0) AS total_amount, COALESCE(AVG(win_bid_price), 0) AS avg_price, MAX(publish_time) AS last_win_time FROM chatbi.bid_biz_win_bid
keywords IS NOT NULL AND keywords != ''
AND keywords LIKE CONCAT('%', #{product}, '%')
keywords NOT LIKE CONCAT('%', #{kw}, '%') AND title NOT LIKE CONCAT('%', #{kw}, '%')
AND province IN
#{p}
AND win_bid_price >= #{minPrice} AND win_bid_price <= #{maxPrice} AND publish_time >= #{beginDate} AND publish_time <= #{endDate}
GROUP BY keywords, province ORDER BY win_count DESC, total_amount DESC LIMIT #{limit}

SELECT win_tenderer AS fullname, win_tenderer AS name, COUNT(*) AS win_count, MAX(province) AS province, MAX(city) AS city, MAX(publish_time) AS latest_pub_time FROM chatbi.bid_biz_win_bid
win_tenderer IS NOT NULL AND win_tenderer != '' AND win_tenderer LIKE CONCAT('%', #{companyName}, '%') AND province = #{province} AND city = #{city}
GROUP BY win_tenderer ORDER BY win_count DESC LIMIT #{limit}

SELECT b.tenderer AS company_name, COUNT(*) AS cooperation_count, COALESCE(SUM(w.win_bid_price), 0) AS cooperation_amount, MAX(w.publish_time) AS last_cooperation_time, GROUP_CONCAT(DISTINCT b.product SEPARATOR ',') AS products FROM chatbi.bid_biz_win_bid w INNER JOIN chatbi.bid_biz_bidding b ON b.project_name = w.project_name
w.win_tenderer = #{companyName} AND b.tenderer IS NOT NULL AND b.tenderer != ''
AND b.province IN
#{p}
w.title LIKE CONCAT('%', #{kw}, '%') OR w.product LIKE CONCAT('%', #{kw}, '%') OR b.keywords LIKE CONCAT('%', #{kw}, '%') OR b.project_name LIKE CONCAT('%', #{kw}, '%')
AND w.win_bid_price >= #{minAmount} AND w.publish_time >= #{beginDate} AND w.publish_time <= #{endDate}
GROUP BY b.tenderer ORDER BY cooperation_count DESC, cooperation_amount DESC LIMIT #{limit}

SELECT
    product AS keyword,
    COUNT(*) AS count,
    COALESCE(SUM(win_bid_price), 0) AS amount
FROM chatbi.bid_biz_win_bid

    win_tenderer = #{companyName}
    AND product IS NOT NULL AND product != ''

        AND province IN

            #{p}


    AND publish_time >= #{beginDate}
    AND publish_time <= #{endDate}

GROUP BY product
ORDER BY count DESC, amount DESC
LIMIT #{limit}

SELECT w2.win_tenderer AS company_name, COUNT(*) AS co_bid_count, MAX(w2.publish_time) AS latest_co_bid_time, GROUP_CONCAT(DISTINCT b.product SEPARATOR ',') AS top_co_bid_products, GROUP_CONCAT(DISTINCT b.tenderer SEPARATOR ',') AS top_co_bid_callers, GROUP_CONCAT(DISTINCT b.province SEPARATOR ',') AS top_co_bid_provinces FROM chatbi.bid_biz_win_bid w1 INNER JOIN chatbi.bid_biz_bidding b ON b.project_name = w1.project_name INNER JOIN chatbi.bid_biz_win_bid w2 ON w2.project_name = w1.project_name
w1.win_tenderer = #{companyName} AND w2.win_tenderer IS NOT NULL AND w2.win_tenderer != '' AND w2.win_tenderer != #{companyName}
GROUP BY w2.win_tenderer ORDER BY co_bid_count DESC LIMIT #{limit}

SELECT w2.win_tenderer AS company_name, COUNT(*) AS co_bid_count, MAX(w2.publish_time) AS latest_co_bid_time, GROUP_CONCAT(DISTINCT w1.tenderer SEPARATOR ',') AS top_co_bid_callers, GROUP_CONCAT(DISTINCT w1.province SEPARATOR ',') AS top_co_bid_provinces, GROUP_CONCAT(DISTINCT w1.product SEPARATOR ',') AS top_co_bid_products FROM chatbi.bid_biz_win_bid w1 INNER JOIN chatbi.bid_biz_win_bid w2 ON w2.tenderer = w1.tenderer AND w2.id != w1.id
w1.win_tenderer = #{companyName} AND w1.tenderer IS NOT NULL AND w1.tenderer != '' AND w2.win_tenderer IS NOT NULL AND w2.win_tenderer != '' AND w2.win_tenderer != #{companyName}
GROUP BY w2.win_tenderer ORDER BY co_bid_count DESC LIMIT #{limit}

SELECT w2.win_tenderer AS company_name, COUNT(*) AS co_bid_count, MAX(w2.publish_time) AS latest_co_bid_time, GROUP_CONCAT(DISTINCT w1.province SEPARATOR ',') AS top_co_bid_provinces, GROUP_CONCAT(DISTINCT w1.product SEPARATOR ',') AS top_co_bid_products, GROUP_CONCAT(DISTINCT w1.tenderer SEPARATOR ',') AS top_co_bid_callers FROM chatbi.bid_biz_win_bid w1 INNER JOIN chatbi.bid_biz_win_bid w2 ON w2.province = w1.province AND SUBSTRING(w2.product, 1, 2) = SUBSTRING(w1.product, 1, 2) AND w2.id != w1.id AND ABS(DATEDIFF(w2.publish_time, w1.publish_time)) <= 90
w1.win_tenderer = #{companyName} AND w1.product IS NOT NULL AND w1.product != '' AND w1.province IS NOT NULL AND w1.province != '' AND w2.win_tenderer IS NOT NULL AND w2.win_tenderer != '' AND w2.win_tenderer != #{companyName}
GROUP BY w2.win_tenderer ORDER BY co_bid_count DESC LIMIT #{limit}

SELECT
province AS bucket_key, industry AS bucket_key, DATE_FORMAT(publish_time, '%Y-%m') AS bucket_key, DATE_FORMAT(publish_time, '%Y-%m-%d') AS bucket_key, province AS bucket_key,
COUNT(*) AS cnt, COALESCE(SUM(win_bid_price), 0) AS sum_amount FROM chatbi.bid_biz_win_bid
title LIKE CONCAT('%', #{kw}, '%') OR project_name LIKE CONCAT('%', #{kw}, '%') OR product LIKE CONCAT('%', #{kw}, '%')
AND province IN
#{p}
AND win_bid_price >= #{minPrice} AND win_bid_price <= #{maxPrice} AND publish_time >= #{beginDate} AND publish_time <= #{endDate}
GROUP BY bucket_key ORDER BY cnt DESC LIMIT #{limit}

SELECT 
FROM chatbi.bid_biz_win_bid

    (
        (service_period IS NOT NULL AND service_period != '')
        OR (service_start IS NOT NULL AND service_start != '')
        OR (service_day IS NOT NULL AND service_day > 0)
    )

        AND province IN

            #{p}



        AND (
          project_name LIKE CONCAT('%', #{keyword}, '%')
          OR win_tenderer LIKE CONCAT('%', #{keyword}, '%')
          OR tenderer LIKE CONCAT('%', #{keyword}, '%')
          OR product LIKE CONCAT('%', #{keyword}, '%')
        )

    AND publish_time >= #{beginDate}
    AND publish_time <= #{endDate}

ORDER BY publish_time DESC, id DESC
LIMIT #{limit}

SELECT win_tenderer_manager AS name, win_tenderer_phone AS phone, win_tenderer_email AS email, COUNT(*) AS contact_count, MAX(publish_time) AS latest_contact_time, GROUP_CONCAT(DISTINCT project_name ORDER BY publish_time DESC SEPARATOR '||') AS related_projects FROM chatbi.bid_biz_win_bid
win_tenderer = #{companyName} AND win_tenderer_manager IS NOT NULL AND win_tenderer_manager != '' AND ( (win_tenderer_phone IS NOT NULL AND win_tenderer_phone != '') OR (win_tenderer_email IS NOT NULL AND win_tenderer_email != '') )
GROUP BY win_tenderer_manager, win_tenderer_phone, win_tenderer_email ORDER BY contact_count DESC LIMIT #{limit}

SELECT tenderer_contact AS name, tenderer_phone AS phone, tenderer_address AS address, COUNT(*) AS contact_count, MAX(publish_time) AS latest_contact_time, GROUP_CONCAT(DISTINCT project_name ORDER BY publish_time DESC SEPARATOR '||') AS related_projects FROM chatbi.bid_biz_bidding
tenderer = #{companyName} AND tenderer_contact IS NOT NULL AND tenderer_contact != '' AND ( (tenderer_phone IS NOT NULL AND tenderer_phone != '') OR (tenderer_address IS NOT NULL AND tenderer_address != '') )
GROUP BY tenderer_contact, tenderer_phone, tenderer_address ORDER BY contact_count DESC LIMIT #{limit}

SELECT agency_contact AS name, agency_phone AS phone, agency AS company, COUNT(*) AS contact_count, MAX(publish_time) AS latest_contact_time, GROUP_CONCAT(DISTINCT project_name ORDER BY publish_time DESC SEPARATOR '||') AS related_projects FROM chatbi.bid_biz_bidding
agency LIKE CONCAT('%', #{companyName}, '%') AND agency_contact IS NOT NULL AND agency_contact != '' AND agency_phone IS NOT NULL AND agency_phone != ''
GROUP BY agency_contact, agency_phone, agency ORDER BY contact_count DESC LIMIT #{limit}

SELECT DATE_FORMAT(publish_time, '%Y-%m') AS month, win_bid_price AS price, project_name AS project_name, win_tenderer AS winner, province AS province FROM chatbi.bid_biz_win_bid
product LIKE CONCAT('%', #{brand}, '%')
AND product LIKE CONCAT('%', #{product}, '%')
AND ( product LIKE CONCAT('%', #{model}, '%') OR project_name LIKE CONCAT('%', #{model}, '%') )
AND win_bid_price IS NOT NULL AND win_bid_price > 0
AND province IN
#{p}
AND publish_time >= #{beginDate} AND publish_time <= #{endDate}
ORDER BY publish_time ASC LIMIT #{limit}
